// Runs the CLI test suite with a throwaway HOME so no test (or anything it spawns: the sidecar, the TUI, PTY drivers)
// can read or write the operator's ~/.nexus or ~/.config/nexus. The real home is passed as NEXUS_TEST_REAL_HOME so the
// guard test can prove the isolation held. Arguments are test files; none means every test/*.test.ts.
// NEXUS_KEEP_TEST_HOME=1 keeps the temporary home for inspection.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const realHome = os.homedir();
const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-test-home-"));

const files = process.argv.length > 2
  ? process.argv.slice(2)
  : fs.readdirSync(path.join(cli, "test")).filter((f) => f.endsWith(".test.ts")).sort().map((f) => path.join("test", f));

const env = {
  ...process.env,
  HOME: home,
  XDG_CONFIG_HOME: path.join(home, ".config"),
  XDG_DATA_HOME: path.join(home, ".local", "share"),
  XDG_STATE_HOME: path.join(home, ".local", "state"),
  XDG_CACHE_HOME: path.join(home, ".cache"),
  NEXUS_TEST_REAL_HOME: realHome,
};
// Rust and Node toolchains installed per user keep working under the throwaway home.
for (const [key, dir] of [["CARGO_HOME", ".cargo"], ["RUSTUP_HOME", ".rustup"]]) {
  if (!env[key] && fs.existsSync(path.join(realHome, dir))) env[key] = path.join(realHome, dir);
/**
 * Shared fakes for provider recovery tests: a virtual clock whose sleep advances time (and lets a test change
 * provider availability between attempts), and a local OpenAI-compatible gateway that can go down and come back.
 */
import http from "node:http";
import { RecoveryCancelled, type RecoveryClock } from "../../src/core/provider_recovery.js";

export interface FakeClock extends RecoveryClock {
  sleeps: number[];
  elapsed(): number;
  /** Time passing without a sleep: a provider taking this long to answer. */
  advance(ms: number): void;
}

export function fakeClock(onSleep?: (ms: number, n: number) => void | Promise<void>, random = 0.5): FakeClock {
  const start = 1_800_000_000_000;
  let t = start;
  const sleeps: number[] = [];
  return {
    sleeps,
    elapsed: () => t - start,
    advance: (ms) => {
      t += ms;
    },
    now: () => t,
    random: () => random,
    async sleep(ms, signal) {
      if (signal?.aborted) throw new RecoveryCancelled();
      sleeps.push(ms);
      t += ms;
      await onSleep?.(ms, sleeps.length);
      if (signal?.aborted) throw new RecoveryCancelled();
    },
  };
}


export type Reply =
  | { kind: "text"; content: string }
  | { kind: "tools"; calls: Array<{ name: string; args: any }> }
  | { kind: "http"; status: number; body?: string; headers?: Record<string, string> }
  | { kind: "reset" }
  | { kind: "empty_stream" }
  /** A streamed response the provider ends with an error frame, as a gateway does at its response time limit. */
  | { kind: "error_frame"; message: string };

export interface Gateway {
  url: string;
  requests: Array<{ id?: string; attempt?: string; previous?: string; authorization?: string; body: any }>;
  probes: number;
  /** Authorization header of every request, chat and /models alike, in arrival order. */
  authorizations: Array<string | undefined>;
  script: (n: number, body: any) => Reply;
  down(): Promise<void>;
  up(): Promise<void>;
  close(): Promise<void>;
}

const sse = (o: unknown) => `data: ${JSON.stringify(o)}\n\n`;

